const $=s=>document.querySelector(s),stage=$('#exhibitSlide'),status=$('#exhibitStatus');
const heading=document.querySelector('.exhibit-heading h1'),subheading=document.querySelector('.exhibit-heading p');if(heading)heading.textContent='인물 데이터셋';if(subheading)subheading.textContent='등록된 기준 사진과 얼굴 분석점을 확인합니다.';document.title='인물 데이터셋 · LOOKALIKE LAB';
const interval=$('#exhibitInterval'),intervals=[3,5,8,15,30];let intervalSeconds=8;
let items=[],position=0,playing=true,timer,generation=0,busy=false,photoBox=null,resizeObserver=null;
const cache=new Map(),visits=new Map();
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function json(url){const response=await fetch(url,{signal:AbortSignal.timeout(12000)});if(!response.ok)throw Error('사진별 분석 정보를 불러오지 못했습니다.');return response.json();}
async function details(item){if(cache.has(item.id))return cache.get(item.id);const [base,extra]=await Promise.all([item.photos.some(p=>p.sample_id.startsWith('base-'))?json('/photo-details/'+encodeURIComponent(item.id)+'.json'):Promise.resolve({}),item.photos.some(p=>!p.sample_id.startsWith('base-'))?json(window.lookalikeDatasetQueue+'/dataset/photos/'+encodeURIComponent(item.id)):Promise.resolve({photos:[]})]);const data={...base};for(const p of extra.photos||[])data[p.sample_id]=p.detail;cache.set(item.id,data);if(cache.size>12)cache.delete(cache.keys().next().value);return data;}
function schedule(){clearTimeout(timer);if(playing&&!document.hidden&&items.length>1&&!busy)timer=setTimeout(()=>move(1),intervalSeconds*1000);}
function controls(){['#exhibitPrev','#exhibitNext'].forEach(s=>$(s).disabled=busy||items.length<2);$('#exhibitPlay').disabled=!items.length;$('#exhibitPlay').textContent=playing?'일시정지':'자동 재생';$('#exhibitPlay').setAttribute('aria-pressed',String(playing));}
function fitPhoto(){if(!photoBox)return;const {area,frame,img}=photoBox;if(!img.naturalWidth)return;const scale=Math.min(area.clientWidth/img.naturalWidth,area.clientHeight/img.naturalHeight,1.8);frame.style.width=img.naturalWidth*scale+'px';frame.style.height=img.naturalHeight*scale+'px';}
async function show(){
 const ticket=++generation;busy=true;clearTimeout(timer);controls();status.textContent='다음 인물을 불러오는 중…';$('#exhibitRetry').hidden=true;
 const item=items[position];if(!item)return;
 try{
  const info=await details(item),photos=item.photos.filter(p=>!p.removed),visit=visits.get(item.id)||0,photo=photos[visit%photos.length],detail=info[photo.sample_id]||{};
  const img=new Image();img.alt=item.name+' 기준 사진';img.decoding='async';await new Promise((resolve,reject)=>{const timeout=setTimeout(()=>reject(Error('사진 응답 시간이 초과됐습니다.')),12000);img.onload=()=>{clearTimeout(timeout);resolve();};img.onerror=()=>{clearTimeout(timeout);reject(Error('사진을 불러오지 못했습니다.'));};img.src=photo.image;});if(ticket!==generation)return;visits.set(item.id,visit+1);
  const points=(detail.landmarks||[]).filter(p=>Array.isArray(p)&&p.length===2&&p.every(v=>Number.isFinite(v)&&v>=0&&v<=1));const keypoints=(detail.keypoints||[]).filter(p=>Array.isArray(p)&&p.length===2&&p.every(v=>Number.isFinite(v)&&v>=0&&v<=1));
  const traits=[['eye_gap','눈 간격'],['eye_tilt','눈 기울기'],['brow_span','눈썹 길이'],['nose_width','코 너비'],['nose_length','코 길이'],['mouth_width','입 너비'],['outline','얼굴 윤곽'],['jaw_depth','턱 깊이']].filter(([key])=>Number.isFinite(detail.traits?.[key]));
  stage.innerHTML='<div class="exhibit-photo-area"><div class="exhibit-photo"></div></div><div class="exhibit-info"><h2>'+esc(item.name)+'</h2><p class="exhibit-group">'+esc(item.group||'인물')+'</p><p class="exhibit-description">'+esc(item.description||'')+'</p><dl>'+traits.map(([key,label])=>'<div><dt>'+label+'</dt><dd>'+detail.traits[key].toFixed(3)+'</dd></div>').join('')+'</dl><p class="exhibit-measure-note">'+(traits.length?'현재 사진의 정규화 비율 · 실제 길이(mm)가 아닙니다.':'이 사진에는 구조 측정값이 없습니다.')+'</p></div>';
  const infoPanel=stage.querySelector('.exhibit-info'),stats=document.createElement('div');stats.className='exhibit-stats';
  stats.innerHTML='<div><strong>'+points.length+'</strong><span>얼굴 분석점</span></div><div><strong>'+keypoints.length+'</strong><span>정렬 기준점</span></div><div><strong>'+(visit%photos.length+1)+'<small> / '+photos.length+'</small></strong><span>기준 사진</span></div>';
  infoPanel.querySelector('dl').before(stats);
  const process=document.createElement('div');process.className='exhibit-process';process.innerHTML='<strong>사진 분석</strong><p>얼굴 검출 <span>→</span> 좌표 정렬 <span>→</span> 특징 비교</p><small>현재 사진에서 얻은 측정값입니다. 사진의 각도와 표정에 따라 달라집니다.</small>';infoPanel.append(process);
  const frame=stage.querySelector('.exhibit-photo'),area=stage.querySelector('.exhibit-photo-area');frame.append(img);img.style.objectFit='contain';img.style.objectPosition='center';
  const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox','0 0 1000 1000');svg.setAttribute('preserveAspectRatio','none');svg.setAttribute('aria-hidden','true');let roi='';if(Array.isArray(detail.bbox)&&detail.bbox.length===4){const [x1,y1,x2,y2]=detail.bbox.map(v=>v*1000);roi='<rect class="roi" x="'+x1+'" y="'+y1+'" width="'+Math.max(0,x2-x1)+'" height="'+Math.max(0,y2-y1)+'"/>';}const anchors=keypoints.map(([x,y],i)=>'<circle class="anchor anchor-'+i+'" cx="'+x*1000+'" cy="'+y*1000+'" r="6"/>').join('');const guide=keypoints.length>=5?'<line class="guide" x1="'+keypoints[0][0]*1000+'" y1="'+keypoints[0][1]*1000+'" x2="'+keypoints[1][0]*1000+'" y2="'+keypoints[1][1]*1000+'"/><line class="guide" x1="'+keypoints[3][0]*1000+'" y1="'+keypoints[3][1]*1000+'" x2="'+keypoints[4][0]*1000+'" y2="'+keypoints[4][1]*1000+'"/>':'';svg.innerHTML=roi+guide+points.map(([x,y],i)=>'<circle class="landmark landmark-'+(i%6)+'" cx="'+x*1000+'" cy="'+y*1000+'" r="2.8"/>').join('')+anchors;svg.style.display=$('#exhibitPoints').getAttribute('aria-pressed')==='true'?'':'none';frame.append(svg);
  resizeObserver?.disconnect();photoBox={frame,area,img};if(window.ResizeObserver){resizeObserver=new ResizeObserver(fitPhoto);resizeObserver.observe(area);}fitPhoto();
  $('#exhibitCount').textContent=(position+1)+' / '+items.length;$('#exhibitDetail').href='/detail?id='+encodeURIComponent(item.id);$('#exhibitDetail').hidden=false;
  status.textContent=points.length?'랜드마크 '+points.length+'개 · 정렬 기준 '+keypoints.length+'개 · 검출 영역 포함 · 기준 사진 '+(visit%photos.length+1)+' / '+photos.length:'이 사진에는 얼굴 분석점이 없습니다. 사진만 전시합니다.';
 }catch(error){if(ticket!==generation)return;status.textContent=error.message+' '+(playing?'잠시 후 다음 인물로 넘어갑니다.':'다음 인물을 선택하거나 다시 불러와 주세요.');$('#exhibitRetry').hidden=false;}
 finally{if(ticket===generation){busy=false;controls();schedule();}}
}
function move(delta){if(busy||!items.length)return;position=(position+delta+items.length)%items.length;show();}
async function load(){clearTimeout(timer);++generation;busy=true;controls();$('#exhibitRetry').hidden=true;status.textContent='공개 데이터셋을 불러오는 중…';try{const [data,excluded]=await Promise.all([window.lookalikeDatasetLoad(),window.lookalikeDatasetState()]);items=data.items.filter(x=>x.type==='human'&&!excluded.has(x.id)&&x.photos.some(p=>!p.removed));for(let i=items.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[items[i],items[j]]=[items[j],items[i]];}if(!items.length)throw Error('전시할 공개 인물 사진이 없습니다.');position=0;await show();}catch(error){busy=false;playing=false;controls();stage.textContent='전시를 시작하지 못했습니다.';status.textContent=error.message;$('#exhibitRetry').hidden=false;}}
$('#exhibitPrev').onclick=()=>move(-1);$('#exhibitNext').onclick=()=>move(1);$('#exhibitPlay').onclick=()=>{playing=!playing;controls();schedule();};interval.onclick=()=>{intervalSeconds=intervals[(intervals.indexOf(intervalSeconds)+1)%intervals.length];interval.textContent='넘김 간격 · '+intervalSeconds+'초';schedule();};$('#exhibitPoints').onclick=()=>{const button=$('#exhibitPoints'),on=button.getAttribute('aria-pressed')!=='true';button.setAttribute('aria-pressed',String(on));button.textContent='분석점 · '+(on?'켜짐':'꺼짐');const svg=stage.querySelector('svg');if(svg)svg.style.display=on?'':'none';};$('#exhibitRetry').onclick=()=>items.length?show():load();
window.addEventListener('resize',fitPhoto);
document.addEventListener('keydown',event=>{if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(event.key)||!event.target.closest('.exhibit-controls'))return;const buttons=Array.from(document.querySelectorAll('.exhibit-controls button:not(:disabled)'));const index=buttons.indexOf(document.activeElement);if(index<0)return;event.preventDefault();buttons[(index+(['ArrowLeft','ArrowUp'].includes(event.key)?-1:1)+buttons.length)%buttons.length].focus();});
$('#exhibitFullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else if($('#exhibition').requestFullscreen)await $('#exhibition').requestFullscreen();else status.textContent='이 브라우저는 전체 화면을 지원하지 않습니다. 가로 방향으로 이용해 주세요.';}catch{status.textContent='전체 화면을 열지 못했습니다. 가로 방향으로 이용해 주세요.';}};
document.addEventListener('fullscreenchange',()=>{$('#exhibitFullscreen').textContent=document.fullscreenElement?'전체 화면 종료':'전체 화면';fitPhoto();});document.addEventListener('visibilitychange',schedule);window.addEventListener('pagehide',()=>{clearTimeout(timer);++generation;resizeObserver?.disconnect();});window.addEventListener('pageshow',event=>{if(event.persisted){busy=false;show();}});load();
